-- ============================================================================
-- REFRESH MEMOS — self-referencing lookups (see 02-create-functions.sql)
-- Generated by rulebook-to-postgres tool. Runs after the seed data. Each round
-- memoises the rows whose self-referenced parents are already memoised, so every
-- __compute call reads its parents from the memo. Rows on a genuine row cycle are
-- never ready and stay unmemoised (their wrapper falls back to __compute).
-- ============================================================================

CREATE OR REPLACE FUNCTION erb_refresh_memo_rule_table_entries() RETURNS integer LANGUAGE plpgsql AS $$
DECLARE n integer; total integer := 0;
BEGIN
  DELETE FROM erb_memo_rule_table_entries_output_value;
  LOOP
    CREATE TEMP TABLE IF NOT EXISTS erb_memo_round (id TEXT PRIMARY KEY) ON COMMIT DROP;
    DELETE FROM erb_memo_round;
    INSERT INTO erb_memo_round SELECT c.rule_table_entry_id::text FROM rule_table_entries c
    WHERE NOT EXISTS (SELECT 1 FROM erb_memo_rule_table_entries_output_value m WHERE m.id = c.rule_table_entry_id::text)
      AND (c.left_partner IS NULL OR NOT EXISTS (SELECT 1 FROM rule_table_entries p WHERE p.rule_table_entry_id = c.left_partner) OR EXISTS (SELECT 1 FROM erb_memo_rule_table_entries_output_value m WHERE m.id = c.left_partner::text))
      AND (c.right_partner IS NULL OR NOT EXISTS (SELECT 1 FROM rule_table_entries p WHERE p.rule_table_entry_id = c.right_partner) OR EXISTS (SELECT 1 FROM erb_memo_rule_table_entries_output_value m WHERE m.id = c.right_partner::text))
    ;
    GET DIAGNOSTICS n = ROW_COUNT;
    EXIT WHEN n = 0;
    INSERT INTO erb_memo_rule_table_entries_output_value(id, val) SELECT c.rule_table_entry_id::text, calc_rule_table_entries_output_value__compute(c.rule_table_entry_id) FROM rule_table_entries c JOIN erb_memo_round r ON r.id = c.rule_table_entry_id::text;
    total := total + n;
  END LOOP;
  RETURN total;
END $$;

CREATE OR REPLACE FUNCTION erb_refresh_memo_time_steps() RETURNS integer LANGUAGE plpgsql AS $$
DECLARE n integer; total integer := 0;
BEGIN
  DELETE FROM erb_memo_time_steps_cumulative_cell_updates;
  LOOP
    CREATE TEMP TABLE IF NOT EXISTS erb_memo_round (id TEXT PRIMARY KEY) ON COMMIT DROP;
    DELETE FROM erb_memo_round;
    INSERT INTO erb_memo_round SELECT c.time_step_id::text FROM time_steps c
    WHERE NOT EXISTS (SELECT 1 FROM erb_memo_time_steps_cumulative_cell_updates m WHERE m.id = c.time_step_id::text)
      AND (c.previous_step IS NULL OR NOT EXISTS (SELECT 1 FROM time_steps p WHERE p.time_step_id = c.previous_step) OR EXISTS (SELECT 1 FROM erb_memo_time_steps_cumulative_cell_updates m WHERE m.id = c.previous_step::text))
    ;
    GET DIAGNOSTICS n = ROW_COUNT;
    EXIT WHEN n = 0;
    INSERT INTO erb_memo_time_steps_cumulative_cell_updates(id, val) SELECT c.time_step_id::text, calc_time_steps_cumulative_cell_updates__compute(c.time_step_id) FROM time_steps c JOIN erb_memo_round r ON r.id = c.time_step_id::text;
    total := total + n;
  END LOOP;
  RETURN total;
END $$;

CREATE OR REPLACE FUNCTION erb_refresh_memo_cells() RETURNS integer LANGUAGE plpgsql AS $$
DECLARE n integer; total integer := 0;
BEGIN
  DELETE FROM erb_memo_cells_value;
  DELETE FROM erb_memo_cells_column_ones;
  DELETE FROM erb_memo_cells_run_start;
  LOOP
    CREATE TEMP TABLE IF NOT EXISTS erb_memo_round (id TEXT PRIMARY KEY) ON COMMIT DROP;
    DELETE FROM erb_memo_round;
    INSERT INTO erb_memo_round SELECT c.cell_id::text FROM cells c
    WHERE NOT EXISTS (SELECT 1 FROM erb_memo_cells_run_start m WHERE m.id = c.cell_id::text)
      AND (c.left_parent IS NULL OR NOT EXISTS (SELECT 1 FROM cells p WHERE p.cell_id = c.left_parent) OR EXISTS (SELECT 1 FROM erb_memo_cells_run_start m WHERE m.id = c.left_parent::text))
      AND (c.center_parent IS NULL OR NOT EXISTS (SELECT 1 FROM cells p WHERE p.cell_id = c.center_parent) OR EXISTS (SELECT 1 FROM erb_memo_cells_run_start m WHERE m.id = c.center_parent::text))
      AND (c.right_parent IS NULL OR NOT EXISTS (SELECT 1 FROM cells p WHERE p.cell_id = c.right_parent) OR EXISTS (SELECT 1 FROM erb_memo_cells_run_start m WHERE m.id = c.right_parent::text))
    ;
    GET DIAGNOSTICS n = ROW_COUNT;
    EXIT WHEN n = 0;
    INSERT INTO erb_memo_cells_value(id, val) SELECT c.cell_id::text, calc_cells_value__compute(c.cell_id) FROM cells c JOIN erb_memo_round r ON r.id = c.cell_id::text;
    INSERT INTO erb_memo_cells_column_ones(id, val) SELECT c.cell_id::text, calc_cells_column_ones__compute(c.cell_id) FROM cells c JOIN erb_memo_round r ON r.id = c.cell_id::text;
    INSERT INTO erb_memo_cells_run_start(id, val) SELECT c.cell_id::text, calc_cells_run_start__compute(c.cell_id) FROM cells c JOIN erb_memo_round r ON r.id = c.cell_id::text;
    total := total + n;
  END LOOP;
  RETURN total;
END $$;

CREATE OR REPLACE FUNCTION erb_refresh_memo_periodicity_candidates() RETURNS integer LANGUAGE plpgsql AS $$
DECLARE n integer; total integer := 0;
BEGIN
  DELETE FROM erb_memo_periodicity_candidates_first_mismatch_from;
  DELETE FROM erb_memo_periodicity_candidates_agreement_run_from;
  LOOP
    CREATE TEMP TABLE IF NOT EXISTS erb_memo_round (id TEXT PRIMARY KEY) ON COMMIT DROP;
    DELETE FROM erb_memo_round;
    INSERT INTO erb_memo_round SELECT c.periodicity_candidate_id::text FROM periodicity_candidates c
    WHERE NOT EXISTS (SELECT 1 FROM erb_memo_periodicity_candidates_agreement_run_from m WHERE m.id = c.periodicity_candidate_id::text)
      AND (c.next_candidate IS NULL OR NOT EXISTS (SELECT 1 FROM periodicity_candidates p WHERE p.periodicity_candidate_id = c.next_candidate) OR EXISTS (SELECT 1 FROM erb_memo_periodicity_candidates_agreement_run_from m WHERE m.id = c.next_candidate::text))
    ;
    GET DIAGNOSTICS n = ROW_COUNT;
    EXIT WHEN n = 0;
    INSERT INTO erb_memo_periodicity_candidates_first_mismatch_from(id, val) SELECT c.periodicity_candidate_id::text, calc_periodicity_candidates_first_mismatch_from__compute(c.periodicity_candidate_id) FROM periodicity_candidates c JOIN erb_memo_round r ON r.id = c.periodicity_candidate_id::text;
    INSERT INTO erb_memo_periodicity_candidates_agreement_run_from(id, val) SELECT c.periodicity_candidate_id::text, calc_periodicity_candidates_agreement_run_from__compute(c.periodicity_candidate_id) FROM periodicity_candidates c JOIN erb_memo_round r ON r.id = c.periodicity_candidate_id::text;
    total := total + n;
  END LOOP;
  RETURN total;
END $$;

CREATE OR REPLACE FUNCTION erb_refresh_memo_tail_cells() RETURNS integer LANGUAGE plpgsql AS $$
DECLARE n integer; total integer := 0;
BEGIN
  DELETE FROM erb_memo_tail_cells_value;
  LOOP
    CREATE TEMP TABLE IF NOT EXISTS erb_memo_round (id TEXT PRIMARY KEY) ON COMMIT DROP;
    DELETE FROM erb_memo_round;
    INSERT INTO erb_memo_round SELECT c.tail_cell_id::text FROM tail_cells c
    WHERE NOT EXISTS (SELECT 1 FROM erb_memo_tail_cells_value m WHERE m.id = c.tail_cell_id::text)
      AND (c.left_parent IS NULL OR NOT EXISTS (SELECT 1 FROM tail_cells p WHERE p.tail_cell_id = c.left_parent) OR EXISTS (SELECT 1 FROM erb_memo_tail_cells_value m WHERE m.id = c.left_parent::text))
      AND (c.center_parent IS NULL OR NOT EXISTS (SELECT 1 FROM tail_cells p WHERE p.tail_cell_id = c.center_parent) OR EXISTS (SELECT 1 FROM erb_memo_tail_cells_value m WHERE m.id = c.center_parent::text))
      AND (c.right_parent IS NULL OR NOT EXISTS (SELECT 1 FROM tail_cells p WHERE p.tail_cell_id = c.right_parent) OR EXISTS (SELECT 1 FROM erb_memo_tail_cells_value m WHERE m.id = c.right_parent::text))
    ;
    GET DIAGNOSTICS n = ROW_COUNT;
    EXIT WHEN n = 0;
    INSERT INTO erb_memo_tail_cells_value(id, val) SELECT c.tail_cell_id::text, calc_tail_cells_value__compute(c.tail_cell_id) FROM tail_cells c JOIN erb_memo_round r ON r.id = c.tail_cell_id::text;
    total := total + n;
  END LOOP;
  RETURN total;
END $$;

CREATE OR REPLACE FUNCTION erb_refresh_memo_tail_checks() RETURNS integer LANGUAGE plpgsql AS $$
DECLARE n integer; total integer := 0;
BEGIN
  DELETE FROM erb_memo_tail_checks_first_violation_from;
  LOOP
    CREATE TEMP TABLE IF NOT EXISTS erb_memo_round (id TEXT PRIMARY KEY) ON COMMIT DROP;
    DELETE FROM erb_memo_round;
    INSERT INTO erb_memo_round SELECT c.tail_check_id::text FROM tail_checks c
    WHERE NOT EXISTS (SELECT 1 FROM erb_memo_tail_checks_first_violation_from m WHERE m.id = c.tail_check_id::text)
      AND (c.next_check IS NULL OR NOT EXISTS (SELECT 1 FROM tail_checks p WHERE p.tail_check_id = c.next_check) OR EXISTS (SELECT 1 FROM erb_memo_tail_checks_first_violation_from m WHERE m.id = c.next_check::text))
    ;
    GET DIAGNOSTICS n = ROW_COUNT;
    EXIT WHEN n = 0;
    INSERT INTO erb_memo_tail_checks_first_violation_from(id, val) SELECT c.tail_check_id::text, calc_tail_checks_first_violation_from__compute(c.tail_check_id) FROM tail_checks c JOIN erb_memo_round r ON r.id = c.tail_check_id::text;
    total := total + n;
  END LOOP;
  RETURN total;
END $$;

CREATE OR REPLACE FUNCTION erb_refresh_memo_diagonals() RETURNS integer LANGUAGE plpgsql AS $$
DECLARE n integer; total integer := 0;
BEGIN
  DELETE FROM erb_memo_diagonals_least_period;
  DELETE FROM erb_memo_diagonals_doubles;
  DELETE FROM erb_memo_diagonals_previous_doubles;
  DELETE FROM erb_memo_diagonals_ones_per_period;
  DELETE FROM erb_memo_diagonals_previous_ones_per_period;
  LOOP
    CREATE TEMP TABLE IF NOT EXISTS erb_memo_round (id TEXT PRIMARY KEY) ON COMMIT DROP;
    DELETE FROM erb_memo_round;
    INSERT INTO erb_memo_round SELECT c.diagonal_id::text FROM diagonals c
    WHERE NOT EXISTS (SELECT 1 FROM erb_memo_diagonals_previous_ones_per_period m WHERE m.id = c.diagonal_id::text)
      AND (c.previous_diagonal IS NULL OR NOT EXISTS (SELECT 1 FROM diagonals p WHERE p.diagonal_id = c.previous_diagonal) OR EXISTS (SELECT 1 FROM erb_memo_diagonals_previous_ones_per_period m WHERE m.id = c.previous_diagonal::text))
      AND (c.opposite_diagonal IS NULL OR NOT EXISTS (SELECT 1 FROM diagonals p WHERE p.diagonal_id = c.opposite_diagonal) OR EXISTS (SELECT 1 FROM erb_memo_diagonals_previous_ones_per_period m WHERE m.id = c.opposite_diagonal::text))
    ;
    GET DIAGNOSTICS n = ROW_COUNT;
    EXIT WHEN n = 0;
    INSERT INTO erb_memo_diagonals_least_period(id, val) SELECT c.diagonal_id::text, calc_diagonals_least_period__compute(c.diagonal_id) FROM diagonals c JOIN erb_memo_round r ON r.id = c.diagonal_id::text;
    INSERT INTO erb_memo_diagonals_doubles(id, val) SELECT c.diagonal_id::text, calc_diagonals_doubles__compute(c.diagonal_id) FROM diagonals c JOIN erb_memo_round r ON r.id = c.diagonal_id::text;
    INSERT INTO erb_memo_diagonals_previous_doubles(id, val) SELECT c.diagonal_id::text, calc_diagonals_previous_doubles__compute(c.diagonal_id) FROM diagonals c JOIN erb_memo_round r ON r.id = c.diagonal_id::text;
    INSERT INTO erb_memo_diagonals_ones_per_period(id, val) SELECT c.diagonal_id::text, calc_diagonals_ones_per_period__compute(c.diagonal_id) FROM diagonals c JOIN erb_memo_round r ON r.id = c.diagonal_id::text;
    INSERT INTO erb_memo_diagonals_previous_ones_per_period(id, val) SELECT c.diagonal_id::text, calc_diagonals_previous_ones_per_period__compute(c.diagonal_id) FROM diagonals c JOIN erb_memo_round r ON r.id = c.diagonal_id::text;
    total := total + n;
  END LOOP;
  RETURN total;
END $$;

CREATE OR REPLACE FUNCTION erb_refresh_memo_terms() RETURNS integer LANGUAGE plpgsql AS $$
DECLARE n integer; total integer := 0;
BEGIN
  DELETE FROM erb_memo_terms_rendered;
  DELETE FROM erb_memo_terms_lean_rendered;
  LOOP
    CREATE TEMP TABLE IF NOT EXISTS erb_memo_round (id TEXT PRIMARY KEY) ON COMMIT DROP;
    DELETE FROM erb_memo_round;
    INSERT INTO erb_memo_round SELECT c.term_id::text FROM terms c
    WHERE NOT EXISTS (SELECT 1 FROM erb_memo_terms_lean_rendered m WHERE m.id = c.term_id::text)
      AND (c.arg1 IS NULL OR NOT EXISTS (SELECT 1 FROM terms p WHERE p.term_id = c.arg1) OR EXISTS (SELECT 1 FROM erb_memo_terms_lean_rendered m WHERE m.id = c.arg1::text))
      AND (c.arg2 IS NULL OR NOT EXISTS (SELECT 1 FROM terms p WHERE p.term_id = c.arg2) OR EXISTS (SELECT 1 FROM erb_memo_terms_lean_rendered m WHERE m.id = c.arg2::text))
      AND (c.arg3 IS NULL OR NOT EXISTS (SELECT 1 FROM terms p WHERE p.term_id = c.arg3) OR EXISTS (SELECT 1 FROM erb_memo_terms_lean_rendered m WHERE m.id = c.arg3::text))
      AND (c.arg4 IS NULL OR NOT EXISTS (SELECT 1 FROM terms p WHERE p.term_id = c.arg4) OR EXISTS (SELECT 1 FROM erb_memo_terms_lean_rendered m WHERE m.id = c.arg4::text))
    ;
    GET DIAGNOSTICS n = ROW_COUNT;
    EXIT WHEN n = 0;
    INSERT INTO erb_memo_terms_rendered(id, val) SELECT c.term_id::text, calc_terms_rendered__compute(c.term_id) FROM terms c JOIN erb_memo_round r ON r.id = c.term_id::text;
    INSERT INTO erb_memo_terms_lean_rendered(id, val) SELECT c.term_id::text, calc_terms_lean_rendered__compute(c.term_id) FROM terms c JOIN erb_memo_round r ON r.id = c.term_id::text;
    total := total + n;
  END LOOP;
  RETURN total;
END $$;

CREATE OR REPLACE FUNCTION erb_refresh_memos() RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  PERFORM erb_refresh_memo_rule_table_entries();
  PERFORM erb_refresh_memo_time_steps();
  PERFORM erb_refresh_memo_cells();
  PERFORM erb_refresh_memo_periodicity_candidates();
  PERFORM erb_refresh_memo_tail_cells();
  PERFORM erb_refresh_memo_tail_checks();
  PERFORM erb_refresh_memo_diagonals();
  PERFORM erb_refresh_memo_terms();
END $$;

SELECT erb_refresh_memos();
